<?php if(!$rows):?><p class="butchery-empty">Aucune alerte dans cette sélection.</p><?php else:?>
<div class="table-responsive"><table class="enterprise-table"><thead><tr><th>Niveau</th><th>Alerte / type</th><th>Créée le</th><th>État</th><th>Lecture</th><th>Action</th></tr></thead><tbody>
<?php foreach($rows as $a):?><tr><td><span class="butchery-status alerts-severity-<?=e($a['severity'])?>"><?=e($severityLabels[$a['severity']]??$a['severity'])?></span></td><td><strong><?=e($a['title'])?></strong><small><?=e($a['type_label'])?></small></td><td data-order="<?=e(strtotime($a['created_at']))?>"><?=e($date($a['created_at']))?></td><td><?=$active($a)?'À traiter':(!empty($a['resolved_at'])?'Résolue':'Inactive')?></td><td><?=empty($a['read_at'])?'Non lue':'Lue'?></td><td><button class="btn-secondary" type="button" data-workspace-modal-open="alert-detail-<?=e($a['id'])?>" aria-label="<?=e('Consulter '.$a['title'])?>">Détails</button></td></tr><?php endforeach;?>
